def _prepare_tzname_delta(self, tzname):
    if '+' in tzname:
        return tzname.replace('+', '-')
    elif '-' in tzname:
        return tzname.replace('-', '+')
    return tzname

def get_count(self, do_count=False):
    """Return a count of the query."""
    if self.can_filter() and not self.has_extra_select() and not self.is_sliced and self.query.granularity is None:
        # Optimization: if no extra select clauses, no slicing, and no explicit granularity,
        # we can just count the number of results directly.
        return self.count()

    # If values() or values_list() was used, the clone needs to be created
    # for the count without the previously specified fields.
    clone = self.clone()
    return clone.do_count(do_count)
